import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { buildSite } from './generator';

const LIVE_RELOAD_SCRIPT = `
<script>
  (function() {
    var socket = new WebSocket('ws://localhost:__PORT__');
    socket.addEventListener('message', function(event) {
      if (event.data === 'reload') {
        window.location.reload();
      }
    });
    socket.addEventListener('close', function() {
      console.log('Live reload disconnected');
    });
  })();
</script>
`;

function injectLiveReload(html: string, port: number): string {
  const script = LIVE_RELOAD_SCRIPT.replace('__PORT__', String(port));
  if (html.includes('</body>')) {
    return html.replace('</body>', script + '</body>');
  }
  return html + script;
}

export interface ServeOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

export function startDevServer(options: ServeOptions): void {
  const { content, output, templates, port } = options;

  const wss = new WebSocketServer({ noServer: true });
  const clients = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => clients.delete(ws));
  });

  const server = http.createServer((req, res) => {
    const url = req.url || '/';
    let filePath = path.join(output, url === '/' ? 'index.html' : url);

    // Remove query strings
    filePath = filePath.split('?')[0];

    const ext = path.extname(filePath).toLowerCase();
    const mimeTypes: Record<string, string> = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.svg': 'image/svg+xml',
    };
    const contentType = mimeTypes[ext] || 'application/octet-stream';

    try {
      let content = fs.readFileSync(filePath);

      if (ext === '.html' || (!ext && !fs.existsSync(filePath))) {
        // If requesting a directory, try index.html
        if (!ext && fs.existsSync(path.join(filePath, 'index.html'))) {
          content = fs.readFileSync(path.join(filePath, 'index.html'));
        }
        const html = injectLiveReload(content.toString('utf-8'), port);
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(html);
        return;
      }

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    } catch {
      // For SPA-like routing or file not found
      // Try serving index.html for any non-file request
      try {
        const indexPath = path.join(output, 'index.html');
        const html = injectLiveReload(fs.readFileSync(indexPath, 'utf-8'), port);
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(html);
      } catch {
        res.writeHead(404);
        res.end('Not Found');
      }
    }
  });

  // Handle WebSocket upgrade
  server.on('upgrade', (req, socket, head) => {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  });

  // File watching with chokidar
  const watcher = chokidar.watch([content, templates], {
    ignoreInitial: true,
    awaitWriteFinish: {
      stabilityThreshold: 100,
      pollInterval: 50,
    },
  });

  let rebuildTimeout: NodeJS.Timeout | null = null;

  function triggerRebuild() {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(() => {
      try {
        console.log('Rebuilding...');
        buildSite(content, output, templates);
        console.log('Rebuild complete');

        // Notify all clients to reload
        for (const client of clients) {
          if (client.readyState === WebSocket.OPEN) {
            client.send('reload');
          }
        }
      } catch (err) {
        console.error('Rebuild error:', (err as Error).message);
      }
    }, 100);
  }

  watcher.on('change', triggerRebuild);
  watcher.on('add', triggerRebuild);
  watcher.on('unlink', triggerRebuild);

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });
}
```

