function injectLiveReload(html: string): string {
  if (html.includes('</body>')) {
    return html.replace('</body>', LIVE_RELOAD_SCRIPT + '</body>');
  }
  return html + LIVE_RELOAD_SCRIPT;
}

export interface ServeOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

export interface DevServer {
  close: () => Promise<void>;
}

export function startDevServer(options: ServeOptions): DevServer {
  const { content, output, templates, port } = options;

  // Initial build
  try {
    buildSite(content, output, templates);
    console.log(`Initial build complete`);
  } catch (err) {
    console.log(`Initial build skipped: ${(err as Error).message}`);
  }

  const server = http.createServer((req, res) => {
    const url = new URL(req.url || '/', `http://localhost:${port}`);
    let filePath = path.join(output, url.pathname);

    if (url.pathname === '/' || !path.extname(filePath)) {
      filePath = path.join(output, url.pathname, 'index.html');
    }

    const ext = path.extname(filePath).toLowerCase();
    const mimeTypes: Record<string, string> = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.jpeg': 'image/jpeg',
      '.svg': 'image/svg+xml',
      '.ico': 'image/x-icon',
    };
    const contentType = mimeTypes[ext] || 'application/octet-stream';

    try {
      let content = fs.readFileSync(filePath);

      if (ext === '.html') {
        const html = injectLiveReload(content.toString('utf-8'));
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(html);
        return;
      }

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    } catch {
      // Try fallback to index.html for SPA routing
      try {
        const indexPath = path.join(output, 'index.html');
        const html = injectLiveReload(fs.readFileSync(indexPath, 'utf-8'));
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(html);
      } catch {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not Found');
      }
    }
  });

  const wss = new WebSocketServer({ server });
  const clients = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => clients.delete(ws));
  });

  // Set up chokidar watcher
  const watchPaths: string[] = [];
  if (fs.existsSync(content)) watchPaths.push(content);
  if (fs.existsSync(templates)) watchPaths.push(templates);

  const watcher = chokidar.watch(watchPaths, {
    ignoreInitial: true,
    awaitWriteFinish: {
      stabilityThreshold: 200,
      pollInterval: 100,
    },
  });

  let rebuildTimeout: ReturnType<typeof setTimeout> | null = null;

  function triggerRebuild() {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(() => {
      try {
        console.log('Rebuilding...');
        buildSite(content, output, templates);
        console.log('Rebuild complete');

        for (const client of clients) {
          if (client.readyState === WebSocket.OPEN) {
            client.send('reload');
          }
        }
      } catch (err) {
        console.error('Rebuild error:', (err as Error).message);
      }
    }, 200);
  }

  watcher.on('change', triggerRebuild);
  watcher.on('add', triggerRebuild);
  watcher.on('unlink', triggerRebuild);

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });

  return {
    close: () => {
      return new Promise<void>((resolve) => {
        watcher.close();
        wss.close();
        server.close(() => resolve());
      });
    }
  };
}
```

