  const watchPaths: string[] = [];
  if (fs.existsSync(content)) watchPaths.push(content);
  if (fs.existsSync(templates)) watchPaths.push(templates);

  console.log('watchPaths:', watchPaths);

  const watcher = chokidar.watch(watchPaths, {
    ignoreInitial: true,
  });

  let rebuildTimeout: ReturnType<typeof setTimeout> | null = null;

  function triggerRebuild() {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(() => {
      try {
        console.log('Rebuilding...');
        buildSite(content, output, templates);
        console.log('Rebuild complete');

        for (const client of clients) {
          if (client.readyState === WebSocket.OPEN) {
            client.send('reload');
          }
        }
      } catch (err) {
        console.error('Rebuild error:', (err as Error).message);
      }
    }, 200);
  }

  watcher.on('change', (filePath: string) => {
    console.log('chokidar: change detected', filePath);
    triggerRebuild();
  });
  watcher.on('add', (filePath: string) => {
    console.log('chokidar: add detected', filePath);
    triggerRebuild();
  });
  watcher.on('unlink', (filePath: string) => {
    console.log('chokidar: unlink detected', filePath);
    triggerRebuild();
  });
  watcher.on('ready', () => {
    console.log('chokidar: ready');
  });
  watcher.on('error', (err: Error) => {
    console.log('chokidar: error', err.message);
  });

  return new Promise((resolve, reject) => {
    let chokidarReady = false;

    watcher.on('ready', () => {
      chokidarReady = true;
      console.log('chokidar: ready');
    });
    watcher.on('error', (err: Error) => {
      console.log('chokidar: error', err.message);
    });

    server.listen(port, () => {
      const actualPort = (server.address() as AddressInfo).port;
      console.log(`Dev server running at http://localhost:${actualPort}`);

      function resolveWhenReady() {
        if (chokidarReady || watchPaths.length === 0) {
          resolve({
            port: actualPort,
            close: async () => {
              if (rebuildTimeout) clearTimeout(rebuildTimeout);
              await watcher.close();
              for (const client of clients) {
                client.terminate();
              }
              wss.close();
              await new Promise<void>((resolveClose) => {
                server.close(() => resolveClose());
              });
            },
          });
        } else {
          setTimeout(resolveWhenReady, 10);
        }
      }

      resolveWhenReady();
    });

    server.on('error', reject);
  });
}

